sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // ==========================================
    // CampusDesk - Create Request API
    // ==========================================

    var body = request.body.data;

    // ------------------------------------------
    // Validate request body
    // ------------------------------------------
    if (!body) {
        response.setStatus(400);
        response.setBody({
            success: false,
            error: "Request body is required"
        });
        return;
    }

    // ------------------------------------------
    // Validate required fields
    // ------------------------------------------
    if (!body.short_description) {
        response.setStatus(400);
        response.setBody({
            success: false,
            error: "short_description is required"
        });
        return;
    }

    if (!body.description) {
        response.setStatus(400);
        response.setBody({
            success: false,
            error: "description is required"
        });
        return;
    }

    // ------------------------------------------
    // CampusDesk Request table
    // ------------------------------------------
    var tableName = "x_1971543_campus_0_campusdesk_request";

    var gr = new GlideRecord(tableName);

    // ------------------------------------------
    // Validate table
    // ------------------------------------------
    if (!gr.isValid()) {
        response.setStatus(500);
        response.setBody({
            success: false,
            error: "CampusDesk request table is invalid",
            table: tableName
        });
        return;
    }

    // ------------------------------------------
    // Initialize new CampusDesk request
    // ------------------------------------------
    gr.initialize();

    // ------------------------------------------
    // Set request fields
    // ------------------------------------------
    gr.setValue("short_description", body.short_description);
    gr.setValue("description", body.description);

    if (body.category) {
        gr.setValue("category", body.category);
    }

    if (body.subcategory) {
        gr.setValue("subcategory", body.subcategory);
    }

    // ------------------------------------------
    // Insert record
    // ------------------------------------------
    var sysId = gr.insert();

    // ------------------------------------------
    // Insert failed
    // ------------------------------------------
    if (!sysId) {
        response.setStatus(500);
        response.setBody({
            success: false,
            error: "Unable to create CampusDesk request"
        });
        return;
    }

    // ------------------------------------------
    // Successful response
    // ------------------------------------------
    response.setStatus(201);

    response.setBody({
        success: true,
        message: "CampusDesk request created successfully",
        request: {
            sys_id: gr.getUniqueValue(),
            number: gr.getValue("number"),
            short_description: gr.getValue("short_description"),
            description: gr.getValue("description"),
            category: gr.getValue("category"),
            subcategory: gr.getValue("subcategory"),
            state: gr.getDisplayValue("state"),
            priority: gr.getDisplayValue("priority"),
            opened_at: gr.getValue("opened_at")
        }
    });

})(request, response);
